UPDATE place_order
SET status = 'REJECTED',
    reject_reason = #{rejectReason}
WHERE po_no = #{poNo}
  AND status = 'PENDING'

UPDATE warehouse_stock
SET qty = qty - #{deductQty}
WHERE stock_no = #{stockNo}
  AND qty >= #{deductQty}
  AND status = 'AVAILABLE'

